import {audioSettings,audioBeats,validateAudio} from './beat-audio-core.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createAudioEditor(root,{patterns,bpm,addFile,fromPad,fromTake,prepare,preview,stopPreview,add,remove,changed,notify}){
 let id='',history=[],redo=[],busy=false,disposed=false,editing=false,confirmDelete=false;const current=()=>patterns().find(p=>p.id===id&&p.kind==='audio')||patterns().find(p=>p.kind==='audio'),q=s=>root.querySelector(s);
 const run=async fn=>{if(busy)return;busy=true;render();try{await fn();}catch(e){if(!disposed)notify(e.message,'error');}finally{busy=false;if(!disposed)render();}};
 function mutate(fn){const p=current();if(!p||editing)return;editing=true;const old=structuredClone(p);try{stopPreview();fn(p);validateAudio(p);p.beats=audioBeats(p,bpm());validateAudio(p);if(JSON.stringify(p)===JSON.stringify(old)){editing=false;return;}history.push({id:p.id,value:old});if(history.length>30)history.shift();redo=[];changed();render();}catch(e){Object.assign(p,old);notify(e.message,'error');render();}finally{editing=false;}}
 function render(){if(disposed)return;const p=current(),s=p&&audioSettings(p);root.innerHTML=`<h2>Audio clips · keep your original</h2><p>Import audio or use a saved microphone pad or shared keyboard/drum take. Edits preserve original PCM and imported file bytes. Independent tempo/pitch uses local WSOLA processing: voices, dense mixes and transients can sound grainy. Preview before exporting. Two-minute prepared-source limit; split longer material.</p><div class="pl-actions"><label class="btn secondary">IMPORT AUDIO<input id="auFile" type="file" accept="audio/*,.wav,.mp3,.ogg,.m4a" ${busy?'disabled':''}></label><button id="auPad" ${busy?'disabled':''}>USE SELECTED PAD / MIC</button><button id="auTake" ${busy?'disabled':''}>USE RECORDED PERFORMANCE</button><button id="auCancel">CANCEL / STOP PREVIEW</button></div><output id="auStatus" aria-live="polite">${busy?'Preparing audio…':''}</output>${p?`<label>Audio source<select id="auSource" ${busy?'disabled':''}>${patterns().filter(p=>p.kind==='audio').map(x=>`<option value="${esc(x.id)}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Name<input id="auName" maxlength="60" value="${esc(p.name)}" ${busy?'disabled':''}></label><canvas id="auWave" width="1000" height="150" aria-label="Actual decoded audio waveform"></canvas><p>${p.duration.toFixed(2)} s original · ${audioBeats(p,bpm()).toFixed(2)} beats processed · source trim highlighted. Playlist clips repeat through their chosen length.</p><div class="pl-actions">${[['start','Trim start · seconds',0,p.duration,.001],['end','Trim end · seconds',.01,p.duration,.001],['speed','Independent speed multiplier',.5,2,.05],['sourceBpm','Source BPM',60,200,1],['pitch','Independent pitch · semitones',-12,12,1],['fine','Fine pitch · cents',-100,100,1]].map(([key,label,min,max,step])=>`<label>${label}<input id="au-${key}" type="number" min="${min}" max="${max}" step="${step}" value="${s[key]}" ${busy?'disabled':''}></label>`).join('')}<label><input id="auSync" type="checkbox" ${s.sync?'checked':''} ${busy?'disabled':''}>Sync to song BPM</label></div><div class="pl-actions"><button id="auPreview" ${busy?'disabled':''}>PREPARE & PREVIEW</button><button id="auAdd" ${busy?'disabled':''}>ADD TO PLAYLIST</button><button id="auDelete" ${busy?'disabled':''}>${confirmDelete?'CONFIRM DELETE SOURCE + LINKED CLIPS':'DELETE SOURCE'}</button><button id="auReset" ${busy?'disabled':''}>RESET EDITS</button><button id="auUndo" ${busy||!history.length?'disabled':''}>UNDO</button><button id="auRedo" ${busy||!redo.length?'disabled':''}>REDO</button></div>`:'<p>No audio clips yet. Import audio or choose a pad above.</p>'}`;
 q('#auFile').onchange=e=>{const file=e.target.files[0];if(file)run(async()=>{const p=await addFile(file);if(p)id=p.id;});};q('#auPad').onclick=()=>run(async()=>{id=(await fromPad()).id;});q('#auTake').onclick=()=>run(async()=>{id=(await fromTake()).id;});q('#auCancel').onclick=()=>stopPreview();if(!p)return;q('#auDelete').onclick=()=>{if(!confirmDelete){confirmDelete=true;render();return;}stopPreview();remove(p.id);confirmDelete=false;history=[];redo=[];id='';render();};q('#auSource').onchange=e=>{confirmDelete=false;stopPreview();id=e.target.value;history=[];redo=[];render();};q('#auName').onchange=e=>mutate(p=>p.name=e.target.value.trim()||'Audio');for(const key of ['start','end','speed','sourceBpm','pitch','fine'])q('#au-'+key).onchange=e=>mutate(p=>{p.audio={...audioSettings(p),[key]:+e.target.value};});q('#auSync').onchange=e=>mutate(p=>p.audio={...s,sync:e.target.checked});q('#auReset').onclick=()=>mutate(p=>p.audio={...audioSettings({duration:p.duration}),sourceBpm:bpm()});for(const [button,from,to]of [['auUndo',history,redo],['auRedo',redo,history]])q('#'+button).onclick=()=>{if(!from.length)return;stopPreview();const row=from.pop(),target=patterns().find(p=>p.id===row.id);if(!target)return;to.push({id:target.id,value:structuredClone(target)});Object.assign(target,row.value);id=target.id;changed();render();};q('#auPreview').onclick=()=>run(async()=>{await prepare();if(!disposed)preview(p);});q('#auAdd').onclick=()=>run(async()=>{await prepare();if(!disposed)add(p.id);});const ctx=q('#auWave').getContext('2d'),wave=p.wave||[];ctx.fillStyle='#10162c';ctx.fillRect(0,0,1000,150);ctx.fillStyle='#63d3cb22';ctx.fillRect(s.start/p.duration*1000,0,(s.end-s.start)/p.duration*1000,150);ctx.strokeStyle='#8bd9cf';ctx.beginPath();wave.forEach(([lo,hi],i)=>{ctx.moveTo(i/wave.length*1000,75+lo*70);ctx.lineTo(i/wave.length*1000,75+hi*70);});ctx.stroke();}
 return{render,select(value){id=value;render();},dispose(){disposed=true;stopPreview();root.replaceChildren();}};
}
